WITH department_totals AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN job_title = 'Manager' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_manager, COUNT(DISTINCT salary) AS unique_managers FROM employees GROUP BY dept_id) SELECT d.dept_name, d.budget, dt.pct_manager, dt.unique_managers FROM departments d LEFT JOIN department_totals dt ON d.id = dt.dept_id WHERE dt.pct_manager > 55 ORDER BY dt.pct_manager DESC, dt.unique_managers DESC;
